options.systemMessage:
=Eres Lucía, asistente de este negocio. Responde la consulta del usuario usando EXCLUSIVAMENTE la BASE DE CONOCIMIENTO de abajo. No inventes nada. Si la respuesta no está en la base, dilo con honestidad ("no tengo esa información, puedo tomar nota y que te contacten"). Español de España, claro y breve. No menciones "base de conocimiento" ni herramientas ni sistemas. Devuelve SOLO JSON: { "response": "string" }

BASE DE CONOCIMIENTO:
{{ $json.kb }}

parameters.jsCode:
let raw = ($json.output ?? '').trim();
if (raw.startsWith('```')) raw = raw.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/,'');
let k = {}; try { k = JSON.parse(raw); } catch (e) { k = { response: raw }; }
return [{ json: { ok: true, intent: 'knowledge', reply_to_user: k.response || '', needs_user_reply: false } }];

const av = $json ?? {};
const tz = $('Output IA → JSON').item.json.tenant_timezone || 'Europe/Madrid';
const slots = Array.isArray(av.slots) ? av.slots : [];
const horas = slots.map(s => DateTime.fromISO(s.start_at).setZone(tz).toFormat('HH:mm'));
return [{ json: {
  date: av.date, available: av.available === true,
  bloques_texto_humano: horas.join(', '),
} }];

const r = $json ?? {};
if (r.status === 'multiple') {
  const nombres = (r.candidates || []).map(c => c.name).join(', ');
  return [{ json: { ok: true, intent: 'list_availability', needs_user_reply: true,
    reply_to_user: `¿Para qué servicio? Tenemos: ${nombres}.` } }];
}
return [{ json: { ok: true, intent: 'list_availability', needs_user_reply: true,
  reply_to_user: 'No encuentro ese servicio. ¿Puedes decírmelo de otra forma?' } }];

const core = $('Output IA → JSON').item.json;
const svc = $json;  // salida de Resolve Service (single)
const tz = core.tenant_timezone || 'Europe/Madrid';
if (!core.date || !core.time) {
  return [{ json: { _incompleto: true, _reason: 'datetime', service_id: svc.service_id } }];
}
const start = DateTime.fromISO(`${core.date}T${core.time}`, { zone: tz });
if (!start.isValid) return [{ json: { _incompleto: true, _reason: 'datetime', service_id: svc.service_id } }];
const phone = (core.contact && core.contact.phone) ? core.contact.phone : null;
const name  = (core.contact && core.contact.name)  ? core.contact.name  : null;
if (!phone && !name) {
  return [{ json: { _incompleto: true, _reason: 'contact', service_id: svc.service_id } }];
}
return [{ json: {
  service_id: svc.service_id,
  start_at: start.toISO(),
  contact_id: null,
  phone, query: name,
  source: 'ai',
  idempotency_key: `${core.sessionID || core.canal || 'lucia'}-${start.toISO()}`,
} }];

const r = $json ?? {};
if (r.ok === true) {
  const a = r.data?.appointment || {};
  const tz = $('Output IA → JSON').item.json.tenant_timezone || 'Europe/Madrid';
  const cuando = a.start_at
    ? DateTime.fromISO(a.start_at).setZone(tz).setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm")
    : '';
  return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: false,
    reply_to_user: (r.message && r.message.includes('idempotente'))
      ? `Tu cita ya estaba reservada para el ${cuando}.`
      : `Listo, cita confirmada para el ${cuando}.`,
    appointment: a } }];
}
const _errs = (r.data && Array.isArray(r.data.errors)) ? r.data.errors.join(' ') : (r.message || '');
if (r.status === 'validation_error' && /contact_id|phone|email|query|identificar al contacto/i.test(_errs)) {
  return [{ json: { ok: false, intent: 'create_appointment', needs_user_reply: true,
    reply_to_user: 'Para cerrar la cita necesito tu nombre y un teléfono de contacto. ¿Me los das?' } }];
}
if (r.status === 'slot_taken') {
  return [{ json: { ok: false, intent: 'create_appointment', needs_user_reply: true,
    reply_to_user: 'Ese horario acaba de ocuparse. ¿Quieres que mire otros huecos de ese día?' } }];
}
if (r.status === 'slot_conflict') {
  return [{ json: { ok: false, intent: 'create_appointment', needs_user_reply: true,
    reply_to_user: 'Ese horario no está disponible ese día. ¿Quieres que te diga los huecos libres?' } }];
}
return [{ json: { ok: false, intent: 'create_appointment', needs_user_reply: true,
  reply_to_user: r.message || 'No he podido crear la cita. ¿Lo intentamos de otra forma?' } }];

const r = $json ?? {};
if (r._reason === 'contact') return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: true,
  reply_to_user: 'Para cerrar la cita necesito tu nombre y un teléfono de contacto. ¿Me los das?' } }];
if (r._reason === 'datetime' || r._no_datetime) return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: true,
  reply_to_user: '¿Qué día y a qué hora te viene bien?' } }];
if (r.status === 'multiple') {
  const nombres = (r.candidates || []).map(c => c.name).join(', ');
  return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: true,
    reply_to_user: `¿Para qué servicio? Tenemos: ${nombres}.` } }];
}
return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: true,
  reply_to_user: 'No encuentro ese servicio. ¿Puedes decírmelo de otra forma?' } }];

const r = $json ?? {};
const failed = r.ok === false || Array.isArray(r.errors) || !!r.error;
if (failed) {
  const errs = Array.isArray(r.errors) ? r.errors.join(' ') : (r.message || r.error || '');
  const needsContact = /contact_id|phone|email|query|identificar al contacto/i.test(errs);
  return [{ json: {
    ok: false, intent: 'create_task', needs_user_reply: true,
    reply_to_user: needsContact
      ? '¿Me dices tu nombre y teléfono para dejar la nota?'
      : 'No he podido anotar la tarea. ¿Lo intentamos de otra forma?',
  } }];
}
return [{ json: { ok: true, intent: 'create_task', needs_user_reply: false,
  reply_to_user: 'Anotado, me encargo de ello.', task: r.data ?? r } }];

const c = $json ?? {};
const intent = (c.intent === 'null' || c.intent === undefined) ? null : (c.intent ?? null);
let reply = (c.reply_to_user || '').toString().trim();
let needs = c.needs_user_reply === true;
if (!reply) {
  // El Core no redactó nada: preguntamos por lo que falte según el flujo.
  if (intent === 'create_appointment') {
    if (!c.service_query) reply = '¿Para qué servicio quieres la cita?';
    else if (!c.date) reply = '¿Qué día te viene bien?';
    else if (!c.time) reply = '¿A qué hora en concreto?';
    else reply = '¿Me dices tu nombre y teléfono para la reserva?';
  } else if (intent === 'list_availability') {
    reply = '¿Qué día quieres que mire?';
  } else if (intent === 'reschedule_appointment' || intent === 'cancel_appointment') {
    reply = '¿De qué cita se trata? Dime el día y la hora.';
  } else if (intent === 'create_task') {
    reply = '¿Qué necesitas exactamente?';
  } else {
    reply = 'Hola, ¿en qué puedo ayudarte?';
  }
  needs = true;
}
return [{ json: { ok: true, intent, needs_user_reply: needs, reply_to_user: reply } }];

const core = $('Output IA → JSON').item.json;
const res = $json ?? {};
const tz = core.tenant_timezone || 'Europe/Madrid';
const phone = core.contact && core.contact.phone ? core.contact.phone : null;
const query = core.contact && core.contact.name ? core.contact.name : null;
const base = { intent: core.intent, phone, query };

if (!res.ok) {
  return [{ json: { ...base, _found: false, _reason: res.status === 'multiple' ? 'varios_contactos' : 'sin_contacto' } }];
}
const appts = Array.isArray(res.data && res.data.appointments) ? res.data.appointments : [];
if (!appts.length) return [{ json: { ...base, _found: false, _reason: 'sin_citas' } }];

let cands = appts.slice();
const ad = core.appointment_date || null;
const at = core.appointment_time || null;
if (ad) {
  const f = cands.filter(a => DateTime.fromISO(a.start_at).setZone(tz).toISODate() === ad);
  if (f.length) cands = f;
}
if (cands.length > 1 && at) {
  const f = cands.filter(a => DateTime.fromISO(a.start_at).setZone(tz).toFormat('HH:mm') === at);
  if (f.length) cands = f;
}
if (cands.length === 1) return [{ json: { ...base, _found: true, appointment_id: cands[0].id } }];
return [{ json: { ...base, _found: false, _reason: 'ambigua',
  opciones: cands.map(a => ({ id: a.id, cuando: DateTime.fromISO(a.start_at).setZone(tz).setLocale('es').toFormat("cccc d 'de' LLLL HH:mm") })) } }];

const m = $json ?? {};
const core = $('Output IA → JSON').item.json;
const tz = core.tenant_timezone || 'Europe/Madrid';
if (!core.date || !core.time) return [{ json: { ...m, _no_new_slot: true } }];
const s = DateTime.fromISO(`${core.date}T${core.time}`, { zone: tz });
if (!s.isValid) return [{ json: { ...m, _no_new_slot: true } }];
return [{ json: { ...m, start_at: s.toISO() } }];

const r = $json ?? {};
const tz = $('Output IA → JSON').item.json.tenant_timezone || 'Europe/Madrid';
if (r.ok === true) {
  const a = (r.data && r.data.appointment) || {};
  const cuando = a.start_at ? DateTime.fromISO(a.start_at).setZone(tz).setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm") : '';
  return [{ json: { ok: true, intent: 'reschedule_appointment', needs_user_reply: false, reply_to_user: `Hecho, tu cita queda para el ${cuando}.`, appointment: a } }];
}
const st = (r.data && r.data.result && r.data.result.status) || r.status;
if (st === 'slot_conflict') return [{ json: { ok:false, intent:'reschedule_appointment', needs_user_reply:true, reply_to_user:'Ese horario no está disponible ese día. ¿Te digo los huecos libres?' } }];
if (st === 'slot_taken')   return [{ json: { ok:false, intent:'reschedule_appointment', needs_user_reply:true, reply_to_user:'Ese horario acaba de ocuparse. ¿Quieres otro?' } }];
return [{ json: { ok:false, intent:'reschedule_appointment', needs_user_reply:true, reply_to_user: r.message || 'No he podido reprogramar la cita.' } }];

const r = $json ?? {};
if (r.ok === true) return [{ json: { ok: true, intent: 'cancel_appointment', needs_user_reply: false, reply_to_user: 'Tu cita queda cancelada.', appointment: (r.data && r.data.appointment) } }];
return [{ json: { ok: false, intent: 'cancel_appointment', needs_user_reply: true, reply_to_user: r.message || 'No he podido cancelar la cita.' } }];

const m = $json ?? {};
const accion = m.intent === 'cancel_appointment' ? 'cancelar' : 'cambiar';
const map = {
  varios_contactos: 'Necesito confirmar quién eres. ¿Me das tu teléfono?',
  sin_contacto: 'No encuentro tus datos. ¿Me dices tu nombre y teléfono?',
  sin_citas: 'No veo ninguna cita próxima a tu nombre.',
  ambigua: 'Tienes varias citas próximas: ' + (m.opciones || []).map(o => o.cuando).join('; ') + '. ¿Cuál quieres ' + accion + '?',
};
return [{ json: { ok: false, intent: m.intent, needs_user_reply: true, reply_to_user: map[m._reason] || 'No he podido localizar la cita.' } }];

const r = $json ?? {};
const code = r.statusCode ?? 0;
const body = (r.body ?? r) || {};
if (code >= 300 || (body && body.errors)) {
  throw new Error('Directus /items/knowledge devolvió ' + code + ': ' + JSON.stringify(body.errors || body));
}
const rows = Array.isArray(body.data) ? body.data : [];
const kb = rows.map(x => `## ${x.title}\n${(x.body || '').trim()}`).join('\n\n').trim();
return [{ json: {
  message: $('Output IA → JSON').item.json.message,
  kb: kb || '(este negocio todavía no tiene información en su base de conocimiento)',
} }];

// Normaliza TODA salida del Core al contrato congelado (n8n/CONTRACT-lucia-core.md).
const s = $json ?? {};
const ok = s.ok !== false;
const intent = (s.intent === undefined || s.intent === 'null') ? null : (s.intent ?? null);
const needs = s.needs_user_reply === true;
// Regla ÚNICA de ciclo de vida de flujo_activo:
//   null   si la operación terminó (needs_user_reply=false) o no hay intent
//   intent en cualquier otro caso (seguimos dentro de la operación)
const flujo_activo = (!needs || !intent) ? null : intent;
// WF19 devuelve la tarea con doble wrap (task.task); lo desanidamos.
const taskObj = (s.task && s.task.task) ? s.task.task : (s.task || null);
const contact_id = s.contact_id
  ?? (s.appointment && s.appointment.contact_id)
  ?? (taskObj && taskObj.contact_id)
  ?? null;
const result = s.appointment ?? taskObj ?? s.result ?? null;
return [{ json: { ok, intent, reply_to_user: s.reply_to_user || '', needs_user_reply: needs, flujo_activo, contact_id, result } }];
